password.html:
{{ template "header.html" . }}
<h1>登录运维工作台</h1><p>使用分配给您的身份账户。登录不会扩大您的组织或资源权限。</p>
<form method="post" action="{{ .PostURL }}"><label for="login">账户邮箱</label><input required id="login" name="login" type="email" autocomplete="username" placeholder="请输入账户邮箱" {{if .Username}}value="{{.Username}}"{{else}}autofocus{{end}}>
<label for="password">登录密码</label><input required id="password" name="password" type="password" autocomplete="current-password" placeholder="请输入登录密码" {{if .Invalid}}autofocus{{end}}>
{{if .Invalid}}<p class="error" role="alert">账户或密码未通过验证，请检查后重试。</p>{{end}}
<button id="submit-login" type="submit">验证身份并登录</button></form>
{{if .BackLink}}<p><a href="{{.BackLink}}">选择其他身份来源</a></p>{{end}}
{{ template "footer.html" . }}
